/// <summary>
/// Get the Invent Transfer Table Ext
/// </summary>
/// <returns>Invent Transfer Table Ext</returns>
public METInventTransferTableExt metInventTransferTableExt()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METInventTransferTableExt));
}

    /// <summary>
    /// pack the Invent Transfer Table Ext
    /// </summary>
    /// <param name = "_metInventTransferTableExt">METInventTransferTableExt to pack</param>
    public void metPackMETInventTransferTableExt(METInventTransferTableExt  _metInventTransferTableExt)
    {
        _metInventTransferTableExt.InventTransferTable = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metInventTransferTableExt);
    }
